add_action( 'woocommerce_before_add_to_cart_button', 'perfectpixel_nyp_field' );
add_filter( 'woocommerce_add_to_cart_validation', 'perfectpixel_nyp_validate', 10, 2 );
add_filter( 'woocommerce_add_cart_item_data', 'perfectpixel_nyp_cart_data', 10, 2 );
add_action( 'woocommerce_before_calculate_totals', 'perfectpixel_nyp_set_price', 20 );

function perfectpixel_nyp_applies( $product_id ) {
	return in_array( (int) $product_id, wp_parse_id_list( '{{nyp_product_ids}}' ), true );
}

function perfectpixel_nyp_posted_amount() {
	return isset( $_POST['perfectpixel_nyp'] ) ? (float) wc_format_decimal( wp_unslash( $_POST['perfectpixel_nyp'] ) ) : 0.0;
}

function perfectpixel_nyp_field() {
	global $product;
	if ( ! $product || ! perfectpixel_nyp_applies( $product->get_id() ) ) {
		return;
	}
	$min = (float) '{{nyp_min_amount}}';
	printf(
		'<p class="perfectpixel-nyp" style="width:100%%"><label for="perfectpixel_nyp">%1$s (%2$s)</label><br><input type="number" id="perfectpixel_nyp" name="perfectpixel_nyp" min="%3$s" step="0.01" value="%3$s" required style="max-width:10em"></p>',
		esc_html( '{{nyp_label}}' ),
		esc_html( get_woocommerce_currency_symbol() ),
		esc_attr( $min )
	);
}

function perfectpixel_nyp_validate( $passed, $product_id ) {
	if ( perfectpixel_nyp_applies( $product_id ) ) {
		$min = (float) '{{nyp_min_amount}}';
		if ( perfectpixel_nyp_posted_amount() < max( 0.01, $min ) ) {
			wc_add_notice( sprintf( '{{nyp_error}}', wp_strip_all_tags( wc_price( $min ) ) ), 'error' );
			return false;
		}
	}
	return $passed;
}

function perfectpixel_nyp_cart_data( $data, $product_id ) {
	if ( perfectpixel_nyp_applies( $product_id ) ) {
		$data['perfectpixel_nyp'] = perfectpixel_nyp_posted_amount(); // Different amounts = separate lines.
	}
	return $data;
}

function perfectpixel_nyp_set_price( $cart ) {
	if ( is_admin() && ! wp_doing_ajax() ) {
		return;
	}
	$min = max( 0.01, (float) '{{nyp_min_amount}}' );
	foreach ( $cart->get_cart() as $item ) {
		if ( isset( $item['perfectpixel_nyp'] ) ) {
			$item['data']->set_price( max( $min, (float) $item['perfectpixel_nyp'] ) );
		}
	}
}
